import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group } = ctx.THREE;

  // Root group for scene placement
  const root = new Group();
  root.position.set(-3.2, -0.3, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Create plane geometry
  const geometry = new PlaneGeometry(2.56, 1.6, 1, 1);

  // Load texture asynchronously
  const texture = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create material with subtle grain effect via TSL nodes
  const uvNode = uv();

  // Simple grain pattern (pseudo-random via sin of uv)
  const grainIntensity = uniform(0.03);
  const grainNoise = mix(
    vec3(1),
    vec3(
      Math.sin(uvNode.x * 100.0) * Math.cos(uvNode.y * 100.0) * 0.5 + 0.5
    ),
    grainIntensity
  );

  const material = new MeshBasicNodeMaterial({
    colorNode: mix(
      uvNode.convert('vec3'),
      grainNoise,
      grainIntensity
    )
  });

  material.map = texture;
  material.needsUpdate = true;

  // Create mesh
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Cleanup function
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  return root;
}
